 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # A solid-colored divider separates two equal-sized panels.
    divider = None
    for r in range(h):
        if len(set(grid[r])) == 1:
            divider = ('row', r)
            break
    if divider is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                divider = ('col', c)
                break
    if divider is None:
        raise ValueError('no solid divider')
    axis, k = divider
    if axis == 'row':
        top, bottom = grid[:k], grid[k+1:]
        n = min(len(top), len(bottom))
        return [[2 if top[i][j] != 0 and bottom[i][j] != 0 else 0
                 for j in range(w)] for i in range(n)]
    left = [row[:k] for row in grid]
    right = [row[k+1:] for row in grid]
    n = min(len(left[0]), len(right[0]))
    return [[2 if left[i][j] != 0 and right[i][j] != 0 else 0
             for j in range(n)] for i in range(h)]
